from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

import fitz
from pptx import Presentation
import win32com.client


def normalize(text: str) -> str:
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


def extract_pdf(path: Path) -> dict:
    document = fitz.open(path)
    pages = []
    for index, page in enumerate(document):
        pages.append({"page": index + 1, "text": normalize(page.get_text("text"))})
    return {"type": "pdf", "page_count": len(document), "pages": pages}


def extract_pptx(path: Path) -> dict:
    presentation = Presentation(path)
    slides = []
    for index, slide in enumerate(presentation.slides):
        blocks = []
        for shape in slide.shapes:
            if getattr(shape, "has_text_frame", False):
                value = normalize(shape.text)
                if value:
                    blocks.append(value)
            if getattr(shape, "has_table", False):
                rows = []
                for row in shape.table.rows:
                    rows.append([normalize(cell.text) for cell in row.cells])
                blocks.append("TABLE\n" + "\n".join(" | ".join(row) for row in rows))
        notes = ""
        try:
            notes = normalize(slide.notes_slide.notes_text_frame.text)
        except (AttributeError, ValueError):
            pass
        slides.append({"slide": index + 1, "blocks": blocks, "notes": notes})
    return {"type": "pptx", "slide_count": len(slides), "slides": slides}


def extract_doc(path: Path) -> dict:
    word = win32com.client.DispatchEx("Word.Application")
    word.Visible = False
    word.DisplayAlerts = 0
    document = None
    try:
        document = word.Documents.Open(str(path.resolve()), ReadOnly=True, AddToRecentFiles=False)
        text = normalize(document.Content.Text)
        tables = []
        for table_index in range(1, document.Tables.Count + 1):
            table = document.Tables(table_index)
            rows = []
            for row_index in range(1, table.Rows.Count + 1):
                row = []
                for column_index in range(1, table.Columns.Count + 1):
                    try:
                        cell_text = table.Cell(row_index, column_index).Range.Text
                    except Exception:
                        cell_text = ""
                    row.append(normalize(cell_text.rstrip("\x07")))
                rows.append(row)
            tables.append({"table": table_index, "rows": rows})
        return {
            "type": "doc",
            "page_count": int(document.ComputeStatistics(2)),
            "paragraph_count": int(document.Paragraphs.Count),
            "text": text,
            "tables": tables,
        }
    finally:
        if document is not None:
            document.Close(False)
        word.Quit()


def extract(path: Path) -> dict:
    suffix = path.suffix.lower()
    if suffix == ".pdf":
        content = extract_pdf(path)
    elif suffix == ".pptx":
        content = extract_pptx(path)
    elif suffix == ".doc":
        content = extract_doc(path)
    else:
        raise ValueError(f"Unsupported file type: {suffix}")
    return {
        "path": str(path.resolve()),
        "size_bytes": path.stat().st_size,
        **content,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", required=True)
    parser.add_argument("files", nargs="+")
    args = parser.parse_args()

    output = Path(args.output)
    output.parent.mkdir(parents=True, exist_ok=True)
    results = [extract(Path(value)) for value in args.files]
    output.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
    print(json.dumps({"output": str(output.resolve()), "files": len(results)}, ensure_ascii=False))


if __name__ == "__main__":
    main()
